const CACHE='love-shell-v1';
const SHELL=['/','/style.css?v=365-1','/intro.css?v=365-1','/auth.css?v=1','/motion.css?v=1','/motion.js?v=1','/intro.js?v=login-1','/app.js?v=login-1','/pwa.css?v=1','/pwa.js?v=1','/icon-192.png','/icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('love-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match('/')));return;}if(SHELL.includes(url.pathname+url.search)||SHELL.includes(url.pathname))event.respondWith(fetch(event.request).catch(()=>caches.match(event.request)));});
